changeSet.sql:
ALTER TABLE users ADD COLUMN two_fa_confirmed_at timestamp(6) with time zone;
ALTER TABLE users ADD COLUMN two_fa_failed_attempts integer NOT NULL DEFAULT 0;
ALTER TABLE users ADD COLUMN two_fa_locked_until timestamp(6) with time zone;

COMMENT ON COLUMN users.two_fa_secret IS
    'ENCRYPTED at rest (see TwoFaSecretConverter) — never plaintext. A readable secret here would let anyone with database access compute valid codes for this account.';
COMMENT ON COLUMN users.two_fa_confirmed_at IS
    'Set only when the user proved their authenticator app holds the secret. two_fa_enabled must never be set without this.';
COMMENT ON COLUMN users.two_fa_locked_until IS
    'Set when two_fa_failed_attempts hits the limit; verification is refused until it passes. Time-based, not permanent: a TOTP user cannot request a fresh code the way a password-reset user can.';

changeSet.rollback:
ALTER TABLE users DROP COLUMN two_fa_confirmed_at;
ALTER TABLE users DROP COLUMN two_fa_failed_attempts;
ALTER TABLE users DROP COLUMN two_fa_locked_until;
